declare(strict_types=1);require_once dirname(__DIR__,2).'/bootstrap.php';$streamId=(int)($_GET['streamId']??0);if($streamId<1)json_response(['message'=>'Geçersiz yayın.'],400);
try{$st=db()->prepare("SELECT * FROM community_goals WHERE stream_id=? ORDER BY FIELD(status,'active','completed','cancelled'),id DESC LIMIT 10");$st->execute([$streamId]);$rows=array_map(static fn($r)=>['id'=>(int)$r['id'],'title'=>$r['title'],'targetAmount'=>(int)$r['target_amount'],'currentAmount'=>(int)$r['current_amount'],'status'=>$r['status'],'progress'=>(int)$r['target_amount']>0?min(100,round((int)$r['current_amount']*100/(int)$r['target_amount'],1)):0,'createdAt'=>$r['created_at']],$st->fetchAll());json_response(['goals'=>$rows]);}catch(Throwable $e){json_response(['message'=>'Topluluk hedefleri yüklenemedi.'],500);} 
